    'INSERT INTO SW_DEFCIVIL.FOLHA_FUNC_RUBRICA_IMPORTADA (ID_RUBRICA_IMPORTADA, ID_FOLHA_FUNCIONARIO, ID_RUBRICA, IND_TIPO, ID_FOLHA_VALORES, PRAZO_PARCELA, PRAZO_TOTAL, IND_PARAMETRO, IND_ORIGEM, VALOR_MULTIPLICADOR, IND_FORMA_ATUALIZACAO, DATA_CADASTRO, DATA_INICIO, DATA_FIM, ANO_REFERENCIA, MES_REFERENCIA, IND_SUBSTITUICAO, OBSERVACAO) VALUES (SW_DEFCIVIL.SQ_PK_RUBRICA_IMPORTADA.NEXTVAL, ' || FF.ID_FOLHA_FUNCIONARIO || ', ' || R.ID_RUBRICA || ', ''' || R.TIPO || ''', ' || FO.ID_FOLHA || ', ''001'', ''001'', ''V'', ''D'', ' || V.VALOR || ', ''D'', ''' || SYSDATE || ''', ''01/06/2026'', ''30/06/2026'', 2026, 6, ''S'', ''<OBSERVACAO>'');' AS INSERT_
FROM
    SW_DEFCIVIL.FOLHA FO
    JOIN SW_DEFCIVIL.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    JOIN SW_DEFCIVIL.FOLHA_FUNC_RUBRICA FR ON FR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FR.ID_RUBRICA
    JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    JOIN VALORES V ON V.MATRICULA = FF.COD_INSTITUCIONAL
UNION ALL
